={
  "model": "anthropic/claude-sonnet-4-6",
  "messages": [
    {
      "role": "system",
      "content": "You are an HR onboarding assistant. Create a 10-day onboarding message sequence for a new employee. Each message should be warm, specific to their role, and actionable. Return ONLY a valid JSON array of 10 objects: [{\"day\": 1, \"message\": \"...\"}]. Keep each message under 150 words. Cover: day 1 welcome, day 2 team intro, day 3 tools setup, day 4 first task, day 5 check-in, day 7 week 1 reflection, day 8 deep dive into role, day 9 meet stakeholders, day 10 30-day goal setting, day 14 two-week check-in."
    },
    {
      "role": "user",
      "content": "New employee: {{ $json.employee_name }}\nRole: {{ $json.role }}\nDepartment: {{ $json.department }}\nManager: {{ $json.manager }}\nStart date: {{ $json.start_date }}"
    }
  ],
  "max_tokens": 2000
}

parameters.jsCode:
const raw = $input.item.json.choices?.[0]?.message?.content || '[]';
let messages;
try {
  const match = raw.match(/\[[\s\S]*\]/);
  messages = JSON.parse(match ? match[0] : raw);
} catch(e) {
  messages = [
    { day: 1, message: `Welcome to the team, {{ $('Extract Employee Data').item.json.employee_name }}! We're thrilled to have you as our new {{ $('Extract Employee Data').item.json.role }}. Today, get settled in, meet the team, and don't hesitate to ask questions. Your manager {{ $('Extract Employee Data').item.json.manager }} is here to help.` }
  ];
}

const slackUserId = $('Extract Employee Data').item.json.slack_user_id;
const startDate = new Date($('Extract Employee Data').item.json.start_date);

const scheduled = messages.map(m => {
  const sendDate = new Date(startDate);
  sendDate.setDate(startDate.getDate() + (m.day - 1));
  // Skip weekends
  if (sendDate.getDay() === 0) sendDate.setDate(sendDate.getDate() + 1);
  if (sendDate.getDay() === 6) sendDate.setDate(sendDate.getDate() + 2);
  return {
    day: m.day,
    message: m.message,
    slack_user_id: slackUserId,
    send_date: sendDate.toISOString().split('T')[0],
    employee_name: $('Extract Employee Data').item.json.employee_name,
    role: $('Extract Employee Data').item.json.role
  };
});

return scheduled.map(s => ({ json: s }));
